def tracer6_revisit2_first_step(gradient):
    """The +0.1 step changes the support at this white, so the line starts at +0.05."""
    if float(gradient) >= 0.:
        raise ValueError('tracer-6 revisit requires a negative derivative')
    return 0.05


def tracer6_revisit2_continuation_step(gradient):
    """Stay at 0.05. A step of 0.1 already changed the support at this white."""
    if float(gradient) == 0.:
        raise ValueError('tracer-6 continuation requires a nonzero derivative')
    return -0.05 if float(gradient) > 0. else 0.05


