                step = -0.1 if accepted_gradient > 0. else 0.1
                midpoint_used = False
                initial_abs = abs(accepted_gradient)
                initial_likelihood = (baseline['terms']['count_log_likelihood']
                                      + baseline['terms']['conditional_FP_log_likelihood'])
